def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row},
             key=lambda v: sum(row.count(v) for row in grid))

    # Find monochrome rectangular frames with background-colored interiors.
    frames = []
    for r0 in range(h - 2):
        for r1 in range(r0 + 2, h):
            for c0 in range(w - 2):
                for c1 in range(c0 + 2, w):
                    color = grid[r0][c0]
                    if color == bg:
                        continue
                    if any(grid[r0][c] != color or grid[r1][c] != color
                           for c in range(c0, c1 + 1)):
                        continue
                    if any(grid[r][c0] != color or grid[r][c1] != color
                           for r in range(r0, r1 + 1)):
                        continue
                    if all(grid[r][c] == bg
                           for r in range(r0 + 1, r1)
                           for c in range(c0 + 1, c1)):
                        frames.append((r0, r1, c0, c1))

    for r0, r1, c0, c1 in frames:
        interior_area = (r1 - r0 - 1) * (c1 - c0 - 1)
        fill = 7 if interior_area % 2 else 2
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                out[r][c] = fill

    return out
